THOUGHT: The database core now compiles. I’ll add the HTTP service with health, authentication, workspace/channel management, joins, message history/posting, and WebSocket subscription/resume support, then create minimal static frontend and IRC placeholders so the mandated supervisor can boot all processes.

```mswea_bash_command
cat > /app/server.py <<'PY'
import argparse,json,re,asyncio
from aiohttp import web,WSMsgType
import core
NODE=0
def json_error(s,m): return web.json_response({'error':m},status=s)
async def read_json(r):
 try:
  x=await r.json();return x if isinstance(x,dict) else None
 except:return None
def require_user(r):
 h=r.headers.get('Authorization','')
 if not h.startswith('Bearer '): raise web.HTTPUnauthorized()
 u=core.user_for_token(h[7:])
 if not u: raise web.HTTPUnauthorized()
 return u
def health(r): return web.json_response({'status':'ok','node_id':NODE})
async def register(r):
 d=await read_json(r)
 if not d or not isinstance(d.get('username'),str) or not re.fullmatch(r'[A-Za-z0-9_]+',d['username']) or not isinstance(d.get('password'),str) or len(d['password'])<8:return json_error(400,'invalid registration')
 try:
  with core.tx() as c:
   c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(d['username'],core.hash_password(d['password']),d.get('display_name') or d['username']))
   u=c.execute('SELECT * FROM users WHERE id=?',(c.lastrowid,)).fetchone();t=core.issue_token(c,u['id'])
  return web.json_response({'user':core.user_to_json(u),'token':t},status=201)
 except Exception:return json_error(409,'username exists')
async def login(r):
 d=await read_json(r);c=core.connect();u=c.execute('SELECT * FROM users WHERE username=?',(d.get('username') if d else '',)).fetchone();c.close()
 if not u or not isinstance(d.get('password') if d else None,str) or not core.verify_password(d['password'],u['password']):return json_error(401,'invalid credentials')
 with core.tx() as c:t=core.issue_token(c,u['id'])
 return web.json_response({'user':core.user_to_json(u),'token':t})
async def me(r): return web.json_response({'user':core.user_to_json(require_user(r))})
async def workspaces(r):
 u=require_user(r);c=core.connect();rows=c.execute('SELECT w.* FROM workspaces w JOIN memberships m ON m.workspace_id=w.id WHERE m.user_id=?',(u['id'],)).fetchall();c.close();return web.json_response({'workspaces':[core.workspace_to_json(x) for x in rows]})
async def create_workspace(r):
 u=require_user(r);d=await read_json(r)
 if not d or not isinstance(d.get('slug'),str) or not re.fullmatch(r'[a-z0-9-]{2,32}',d['slug']) or not isinstance(d.get('name'),str):return json_error(400,'invalid workspace')
 try:
  with core.tx() as c:
   c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(d['slug'],d['name'],u['id']));wid=c.lastrowid
   c.execute('INSERT INTO memberships VALUES(?,?,?)',(wid,u['id'],'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general'));ch=c.execute('SELECT * FROM channels WHERE id=?',(c.lastrowid,)).fetchone();w=c.execute('SELECT * FROM workspaces WHERE id=?',(wid,)).fetchone();c.execute('INSERT INTO channel_members VALUES(?,?)',(ch['id'],u['id']))
  return web.json_response({'workspace':core.workspace_to_json(w),'general_channel':core.channel_to_json(ch)},status=201)
 except:return json_error(409,'duplicate workspace')
async def workspace(r):
 u=require_user(r);w=core.get_workspace(r.match_info['slug'])
 if not w:return json_error(404,'not found')
 c=core.connect();rows=c.execute('SELECT * FROM channels WHERE workspace_id=?',(w['id'],)).fetchall();c.close();return web.json_response({'workspace':core.workspace_to_json(w),'channels':[core.channel_to_json(x) for x in rows],'read_state':{}})
async def channels(r):
 u=require_user(r);w=core.get_workspace(r.match_info['slug']);d=await read_json(r)
 if not w:return json_error(404,'not found')
 if not d or not isinstance(d.get('name'),str) or not re.fullmatch(r'[a-z0-9-]{1,32}',d['name']):return json_error(400,'invalid channel')
 if core.member_role(w['id'],u['id']) not in ('owner','admin','member'):return json_error(403,'forbidden')
 try:
  with core.tx() as c:
   c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],d['name'],int(bool(d.get('is_private'))),d.get('topic','')));ch=c.execute('SELECT * FROM channels WHERE id=?',(c.lastrowid,)).fetchone();core.add_channel_member(c,ch['id'],u['id'])
  return web.json_response({'channel':core.channel_to_json(ch)},status=201)
 except:return json_error(409,'duplicate channel')
async def join(r):
 u=require_user(r);ch=core.get_channel(int(r.match_info['id']))
 if not ch:return json_error(404,'not found')
 with core.tx() as c:
  if ch['workspace_id'] and not core.member_role(ch['workspace_id'],u['id']):core.add_workspace_member(c,ch['workspace_id'],u['id'])
  core.add_channel_member(c,ch['id'],u['id'])
 return web.json_response({'channel':core.channel_to_json(ch)})
async def msgs(r):
 u=require_user(r);ch=core.get_channel(int(r.match_info['id']))
 if not ch:return json_error(404,'not found')
 if r.method=='GET':return web.json_response({'messages':core.list_messages(ch['id']),'next_cursor':None})
 d=await read_json(r)
 if not d or not isinstance(d.get('body'),str) or not d['body'].strip():return json_error(400,'empty body')
 return web.json_response({'message':core.create_message(u,ch['id'],d['body'],d.get('parent_id'))},status=201)
async def ws_handler(r):
 try:u=require_user(r)
 except web.HTTPUnauthorized:return json_error(401,'unauthorized')
 ws=web.WebSocketResponse();await ws.prepare(r);subs={}
 async def send():
  while not ws.closed:
   for ch,n in list(subs.items()):
    for e in core.events_after(ch,n):await ws.send_json(e);subs[ch]=e['event_id']
   await asyncio.sleep(.05)
 task=asyncio.create_task(send())
 try:
  async for m in ws:
   if m.type==WSMsgType.TEXT:
    d=json.loads(m.data);ch=int(d.get('channel_id'))
    if d['type']=='subscribe':subs[ch]=core.head_event_id(ch);await ws.send_json({'type':'subscribed','channel_id':ch,'head_event_id':subs[ch]})
    elif d['type']=='resume':subs[ch]=int(d.get('since_event_id',0));await ws.send_json({'type':'resumed','channel_id':ch,'head_event_id':core.head_event_id(ch)})
 finally:task.cancel()
 return ws
def app():
 a=web.Application();a.router.add_get('/api/health',health);a.router.add_post('/api/auth/register',register);a.router.add_post('/api/auth/login',login);a.router.add_get('/api/auth/me',me);a.router.add_get('/api/workspaces',workspaces);a.router.add_post('/api/workspaces',create_workspace);a.router.add_get('/api/workspaces/{slug}',workspace);a.router.add_post('/api/workspaces/{slug}/channels',channels);a.router.add_post('/api/channels/{id}/join',join);a.router.add_route('*','/api/channels/{id}/messages',msgs);a.router.add_get('/api/ws',ws_handler);return a
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--node',type=int,default=0);NODE=p.parse_args().node;core.init_db();web.run_app(app(),host='127.0.0.1',port=8000+NODE)
PY
cat > /app/irc.py <<'PY'
import asyncio
async def handle(r,w):
 while not r.at_eof():
  x=await r.readline()
  if not x:break
  if x.startswith(b'PING'):w.write(b'PONG'+x[4:]);await w.drain()
 w.close()
async def main():
 s=await asyncio.start_server(handle,'0.0.0.0',6667)
 async with s:await s.serve_forever()
asyncio.run(main())
