steps.message:
THOUGHT: E5 failures are because the current app.js only supports login and has no signup, workspace, channel, or logout flows. I’ll replace it with a single-page implementation that binds the pinned controls, supports register/login, token storage, workspace/channel creation and switching, visible validation errors, and logout restoration.

```mswea_bash_command
cat > /app/static/app.js <<'EOF'
let state={token:localStorage.getItem('huddle.token')||'',user:null,workspace:null,channel:null,channels:[],signup:false};
const $=s=>document.querySelector(s);
async function api(path,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{})};let r=await fetch('/api'+path,opt);let x={};try{x=await r.json()}catch{};if(!r.ok)throw Object.assign(new Error(x.error||'Request failed'),{data:x,status:r.status});return x}
function showAuth(){ $('#auth-modal').style.display='block'; document.querySelector('.app').style.display='none'}
function hideAuth(){ $('#auth-modal').style.display='none'; document.querySelector('.app').style.display='flex'}
function error(text){let e=$('[data-testid=auth-error]');e.textContent=text;e.style.display='block'}
function renderChannels(){let box=$('[data-testid=channel-list]');box.innerHTML='';state.channels.forEach(c=>{let b=document.createElement('button');b.className='channel-entry';b.dataset.testid='channel-entry';b.dataset.channelId=c.id;b.dataset.channelName=c.name;b.textContent='# '+c.name;b.onclick=()=>selectChannel(c);box.appendChild(b)})}
async function loadWorkspace(){let x=await api('/workspaces/'+state.workspace.slug);state.channels=x.channels||[];renderChannels();if(state.channels.length)selectChannel(state.channels[0]);$('#workspace-header').textContent=state.workspace.name}
